#include <algorithm>
#include <array>
#include <bit>
#include <cstdint>
#include <iostream>
#include <random>
#include <vector>
using U=uint32_t;struct G{int n;std::vector<U>a;};void add(G&g,int x,int y){g.a[x]|=U(1)<<y;g.a[y]|=U(1)<<x;}int pc(U x){return std::popcount(x);}bool conn(const G&g,U del){U r=((U(1)<<g.n)-1)&~del;if(!r)return true;U seen=r&-r,fr=seen;while(fr){U b=fr&-fr;fr^=b;int v=std::countr_zero(b);U nx=g.a[v]&r&~seen;seen|=nx;fr|=nx;}return seen==r;}bool c5(const G&g){for(int v=0;v<g.n;v++)if(pc(g.a[v])<5)return false;U all=(U(1)<<g.n)-1;for(U s=0;s<=all;s++)if(pc(s)<=4&&!conn(g,s))return false;return true;}struct S{const G&g;U all;std::vector<uint8_t>co;std::vector<U>ex;std::array<U,7>b{};uint64_t nodes=0,cap;S(const G&x,uint64_t c):g(x),all((U(1)<<x.n)-1),co(U(1)<<x.n),ex(U(1)<<x.n),cap(c){for(U s=1;s<=all;s++){U q=s&-s;int v=std::countr_zero(q);ex[s]=ex[s^q]|g.a[v];U seen=q,fr=q;while(fr){U z=fr&-fr;fr^=z;int w=std::countr_zero(z);U nx=g.a[w]&s&~seen;seen|=nx;fr|=nx;}co[s]=seen==s;}}int dfs(U r,int k,int m){if(++nodes>cap)return -1;if(k==7)return 1;if(pc(r)<7-k)return 0;U p=r&-r,rest=r^p;int mx=pc(r)-(7-k)+1;for(int sz=1;sz<=mx;sz++){for(U s=rest;;s=(s-1)&rest){if(pc(s)==sz-1){U q=s|p;if(co[q]){int mm=m;for(int i=0;i<k;i++)if(!(ex[q]&b[i])){if(++mm>1)break;}if(mm<=1){b[k]=q;int z=dfs(r^q,k+1,mm);if(z)return z;}}}if(!s)break;}}return dfs(r^p,k,m);}int run(){return dfs(all,0,0);}};bool indconn(const G&g,int a,int b){U m=0;for(int i=a;i<b;i++)m|=U(1)<<i;U seen=m&-m,fr=seen;while(fr){U q=fr&-fr;fr^=q;int v=std::countr_zero(q);U nx=g.a[v]&m&~seen;seen|=nx;fr|=nx;}return seen==m;}bool full(const G&g,int a,int b){U m=0;for(int i=a;i<b;i++)m|=U(1)<<i;for(int r=0;r<6;r++)if(!(g.a[r]&m))return false;return true;}void low(G&g,bool k3){add(g,6,7);add(g,6,8);if(k3)add(g,7,8);for(int r:{0,1,2})add(g,6,r);for(int v:{7,8})for(int r:{0,3,4,5})add(g,v,r);}template<class T>void reproducible_shuffle(std::vector<T>&v,std::mt19937_64&rng){for(size_t i=v.size();i>1;i--)std::swap(v[i-1],v[rng()%i]);}int main(){std::mt19937_64 rng(123123);int trials=10000;for(bool k3:{false,true})for(int orient=0;orient<2;orient++){int built=0,five=0,pos=0,unk=0,neg=0;uint64_t mx=0;for(int t=0;t<trials;t++){G g{15,std::vector<U>(15)};low(g,k3);add(g,0,1);std::vector<std::pair<int,int>>var;for(int i=9;i<15;i++)for(int j=i+1;j<15;j++)var.push_back({i,j});for(int i=9;i<15;i++)for(int r=0;r<6;r++)var.push_back({i,r});reproducible_shuffle(var,rng);int fixed=(k3?14:13)+1;int need=53-fixed;for(int i=0;i<need;i++)add(g,var[i].first,var[i].second);if(!indconn(g,9,15)||!full(g,9,15))continue;int u=orient?1:0;U cm=0;for(int i=9;i<15;i++)cm|=U(1)<<i;int req=orient?3:1;if(pc(g.a[u]&cm)!=req)continue;built++;if(!c5(g))continue;five++;S s(g,3000000);int r=s.run();mx=std::max(mx,s.nodes);if(r==1)pos++;else if(r<0)unk++;else{neg++;break;}}std::cout<<(k3?"K3":"P3")<<" orient="<<orient<<" built="<<built<<" five="<<five<<" pos="<<pos<<" unk="<<unk<<" neg="<<neg<<" maxnodes="<<mx<<"\n";}}
